window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["peft-lora"]={"title":"PEFT / LoRA：冻结主干，只学习低秩权重增量","subtitle":"从 ΔW=BA、rank 与缩放，到可训练参数账、QLoRA、目标模块、合并版本和多适配器干扰。","thesis":"LoRA 假设任务适配所需的权重变化可由低秩矩阵近似，用两个小矩阵表示 ΔW，在冻结基座时减少梯度、优化器状态和检查点。它不会按同等比例减少<b>前向计算、训练激活或行为风险</b>，rank 与注入层决定表达上限。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"rank=8 时，16.8M 参数的矩阵","rule":"A+B 参数","steps":"65,536 / 16,777,216 ≈ 0.391%","interpretation":"两个低秩矩阵只训练约 0.39% 参数"}}],"formulas":[{"id":"peft-lora-forward","section":2,"formulaIndex":1,"symbols":[{"name":"h","meaning":"基座分支与 LoRA 分支相加后的层输出","evidence":"h 是 d 维输出"},{"name":"W","meaning":"被冻结且仍参与计算的基座权重矩阵","evidence":"W 是冻结的 d×k 基座权重"},{"name":"x","meaning":"送入当前线性层的输入向量","evidence":"x 是 k 维输入"},{"name":"α","meaning":"控制低秩分支相对强度的缩放系数","evidence":"α 是缩放系数"},{"name":"r","meaning":"低秩增量可以表达的秩上限和中间维数","evidence":"r 是秩上限"},{"name":"A","meaning":"把 k 维输入压缩到 r 维的小矩阵","evidence":"A 先把 k 维输入压到 r 维"},{"name":"B","meaning":"把 r 维表示展开到 d 维的小矩阵","evidence":"B 再把 r 维展开到 d 维"},{"name":"ℝ","meaning":"矩阵元素取值所在的实数集合","evidence":"ℝ 表示矩阵元素是实数"},{"name":"k","meaning":"当前线性层输入向量的维数","evidence":"x 是 k 维输入"},{"name":"d","meaning":"当前线性层输出向量的维数","evidence":"h 是 d 维输出"}]}],"termReviews":[{"section":5,"reviewedAt":"2026-07-26","terms":[{"name":"降维","meaning":"把向量的坐标数量从较多变成较少","purpose":"让 MLP 的中间表示回到主干所需的维度","definitionEvidence":"把向量的坐标数量从较多变成较少","purposeEvidence":"用于让 MLP 输出回到主干维度"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"LoRA 用两个窄矩阵的乘积表示基座权重的低秩任务增量。","evidence":"低秩的是增量，不是基座"},"problem":{"answer":"它避免为适配任务而让大权重矩阵的每个元素都独立训练和存储。","evidence":"为何不必让每个元素都独立变化"},"inputOutput":{"answer":"输入仍是 k 维向量，输出仍是 d 维向量，并叠加一个低秩分支。","evidence":"输入仍是原层的 k 维向量"},"mechanism":{"answer":"若任务变化只有少数独立方向，就用 B 与 A 的乘积近似 ΔW。","evidence":"可以由两个更窄的矩阵相乘得到"},"interpretation":{"answer":"较低有效秩表示任务适配可由少数变化方向表达，并非基座本身很小。","evidence":"包含多少个彼此独立的变化方向"},"boundary":{"answer":"低秩是经验假设，复杂迁移或新能力可能需要更高秩、更多层或全量微调。","evidence":"这是经验假设，不是所有任务定理"}},{"section":2,"definition":{"answer":"LoRA 前向把冻结基座输出与经过缩放的低秩增量输出相加。","evidence":"LoRA 分支怎样与原线性层相加"},"problem":{"answer":"它明确低秩分支怎样改变原层输出，以及 rank 和 alpha 怎样控制表达与尺度。","evidence":"α/r 控制更新尺度"},"inputOutput":{"answer":"输入是 k 维 x，输出是 d 维 h，A 与 B 在中间使用 r 维表示。","evidence":"x 是 k 维输入"},"mechanism":{"answer":"A 先压缩、B 再展开并乘 alpha/r，然后与 W x 相加。","evidence":"比例 α/r 控制低秩分支相对基座分支的强度"},"interpretation":{"answer":"rank 改变可表达方向，alpha 改变分支强度，必须联合消融而非孤立比较。","evidence":"必须和 α、层、数据一起消融"},"boundary":{"answer":"冻结 W 省去其更新状态，但梯度传播、基座计算和训练激活仍存在。","evidence":"基座计算与激活并未消失"}},{"section":3,"definition":{"answer":"参数账按 A 的 r×k 与 B 的 d×r 元素数相加，计算 LoRA 可训练参数。","evidence":"A+B 参数"},"problem":{"answer":"它量化一个大投影矩阵在指定 rank 下实际减少多少可训练状态。","evidence":"4096×4096 投影省多少可训练参数"},"inputOutput":{"answer":"输入是 d、k 和 rank，输出是 A+B 参数数、相对比例与容量判断。","evidence":"rank=8 时，16.8M 参数的矩阵"},"mechanism":{"answer":"rank 八时两个矩阵各有 32768 个元素，合计 65536 个可训练参数。","evidence":"32,768"},"interpretation":{"answer":"约百分之零点三九一是可训练参数比例，不是总显存或总计算比例。","evidence":"可训练比例 65,536 / 16,777,216 ≈ 0.391%"},"boundary":{"answer":"更低 rank 可能欠拟合，更高 rank 增加容量、优化器状态和过拟合风险。","evidence":"容量高、状态更多"}},{"section":4,"definition":{"answer":"LoRA 主要省冻结权重的梯度、优化器状态和任务检查点，而非全部训练资源。","evidence":"不为冻结 W 保存梯度与 Adam 一、二阶状态"},"problem":{"answer":"它解释训练参数只有百分之零点三九时，显存为何不会同比缩小。","evidence":"训练显存为什么不会缩到 0.39%"},"inputOutput":{"answer":"输入是权重、梯度、状态和激活清单，输出是全量微调与 LoRA 资源账。","evidence":"适配器检查点也小"},"mechanism":{"answer":"冻结项不存梯度和优化器状态，但完整基座仍前向且保存反向所需激活。","evidence":"基座权重、前向激活、反向所需中间值"},"interpretation":{"answer":"激活可随 batch、序列和层数成为主导，参数比例不能直接预测峰值显存。","evidence":"激活常随 batch、序列和层数主导"},"boundary":{"answer":"大矩阵 W x 仍占主要 FLOPs，因此训练速度不会按参数比例加速。","evidence":"训练速度也不会按参数比例加速"}},{"section":5,"definition":{"answer":"目标模块选择决定 LoRA 允许任务数据改动 Transformer 的哪些计算环节。","evidence":"选择允许任务数据改动哪些计算环节"},"problem":{"answer":"它权衡少量目标层的可控和节省，与覆盖更多层的适配容量。","evidence":"只对 Q/V 投影加 LoRA 与覆盖所有线性层"},"inputOutput":{"answer":"输入是候选模块、rank 和固定预算，输出是任务、通用、安全与分布外指标。","evidence":"输出是各方案的任务、通用、安全和未见分布指标"},"mechanism":{"answer":"注意力投影改变寻址与信息混合，MLP 投影改变每层特征变换。","evidence":"分别参与“找谁、怎样匹配、取什么信息、怎样送回主干”"},"interpretation":{"answer":"更多层令训练损失下降但留出收益停滞，表示容量未转化为泛化。","evidence":"容量没有转化为泛化"},"boundary":{"answer":"模块名称随架构变化，匹配失败可静默训练零参数，启动时必须断言。","evidence":"可能静默训练零参数"}},{"section":6,"definition":{"answer":"QLoRA 用低位量化存储冻结基座，同时只训练独立的 LoRA 适配器。","evidence":"量化后的冻结基座 + 可训练 LoRA"},"problem":{"answer":"它进一步降低基座权重存储，使有限显存也能进行参数高效微调。","evidence":"基座是 4-bit"},"inputOutput":{"answer":"输入是量化基座、LoRA 配置和数据，输出是适配器与完整量化训练配方。","evidence":"输出是适配器及其量化训练配方"},"mechanism":{"answer":"低位权重在计算时反量化参与矩阵乘，反向梯度通过运算传给 A 与 B。","evidence":"基座参数不更新，但这次矩阵运算仍把梯度传给 A/B"},"interpretation":{"answer":"分离推理与合并后再量化的差异应归因到不同产物路径，并分别评测。","evidence":"不是同一产物"},"boundary":{"answer":"QLoRA 同时受量化误差和低秩容量限制，显存下降也不等于 FLOPs 同比下降。","evidence":"训练内存下降不等于训练 FLOPs 同比例下降"}},{"section":7,"definition":{"answer":"适配器可与基座分离动态挂载，也可把增量合并回基座形成单一权重。","evidence":"合并 W←W+(α/r)BA"},"problem":{"answer":"它权衡固定部署的简单推理与多租户切换、回滚和版本治理。","evidence":"为什么文件更简单却更难回滚"},"inputOutput":{"answer":"输入是基座、适配器和合并配方，输出是分离服务或新的合并模型产物。","evidence":"分离保存便于按租户/任务切换和回滚"},"mechanism":{"answer":"合并消除额外分支乘法，分离则由路由在请求时选择和加载适配器。","evidence":"可消除分支额外矩阵乘"},"interpretation":{"answer":"分离小文件利于切换，合并简化推理但失去独立开关并产生新大文件。","evidence":"失去独立开关"},"boundary":{"answer":"适配器必须绑定基座和配置血缘，合并及量化顺序也会改变最终行为。","evidence":"必须绑定基座哈希、tokenizer、目标模块"}},{"section":8,"definition":{"answer":"少量低秩参数可经多层放大全局重排 logits，因此行为变化不按参数比例缩小。","evidence":"不按改动数量线性变化"},"problem":{"answer":"它解释小适配器为何既能学会格式，也可能破坏拒答和通用能力。","evidence":"为什么能让模型学会新格式，也能破坏安全拒答"},"inputOutput":{"answer":"输入是适配数据和低秩更新，输出是所有输入上改变后的概率与行为。","evidence":"少量低秩更新作用于多层和所有输入"},"mechanism":{"answer":"参数方向经层间放大改变最终 logits，窄数据还会形成模板、遗忘或触发器。","evidence":"能显著重排 logits"},"interpretation":{"answer":"目标指标提高不能代表风险同比很小，必须同时观察通用与安全回归。","evidence":"对目标、通用、长上下文、多语言、安全、工具和校准做回归"},"boundary":{"answer":"第三方适配器属于可执行模型制品，应按模型权重权限治理来源、签名和加载。","evidence":"加载权限应等同模型代码/权重"}},{"section":9,"definition":{"answer":"方案选择按知识更新、行为稳定、资源和能力重塑深度匹配不同技术。","evidence":"何时选 LoRA，何时选其他方案"},"problem":{"answer":"它避免把所有知识、格式、能力或端侧体积需求都错误地交给 LoRA。","evidence":"任务只需要新知识、固定格式或深层能力改变时"},"inputOutput":{"answer":"输入是任务性质和同预算基线，输出是提示、检索、LoRA、全量微调等选择。","evidence":"比较同预算基线"},"mechanism":{"answer":"比较每个方案达到成功门槛后的训练、服务、路由、评测与维护总成本。","evidence":"每成功任务成本"},"interpretation":{"answer":"增加 rank 或层数后留出增益平台且回归上升，说明应停止扩容量。","evidence":"真实留出增益平台而通用/安全退化上升"},"boundary":{"answer":"知识频繁更新优先检索，端侧压缩还需量化或蒸馏，广泛重塑可能要全量微调。","evidence":"知识频繁更新优先 RAG/工具"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>推导 LoRA 参数量和前向；区分训练状态与总显存；理解 rank/alpha/目标模块；安全合并、切换与评测适配器。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>任务适配为什么可能是低秩变化<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">一个 d×k 大矩阵为何不必让每个元素都独立变化？</p><p>先把词说清：线性层的基座权重 <code>W</code> 把 k 维输入变成 d 维输出；微调想学的是它的改变量 <code>ΔW</code>。矩阵的“秩”可先理解为它包含多少个彼此独立的变化方向。若任务只需少数方向，ΔW 就可以由两个更窄的矩阵相乘得到，而不必独立存下 d×k 个改变量。</p><p>预训练已学到通用表示，新任务可能只需沿少数方向调整注意力或特征。若 ΔW 的有效秩很低，可用 B(d×r)A(r×k) 表示，r 远小于 d、k。输入仍是原层的 k 维向量，输出仍是 d 维向量，只是额外叠加一条低秩分支。</p><p>这是经验假设，不是所有任务定理。复杂领域迁移、多任务冲突或从未学过的能力可能需要更高 rank、更多目标层或全量微调。</p><div class=\"dd-note\"><b>低秩的是增量，不是基座。</b>　推理仍需完整 W；LoRA 只以小分支改变其输出。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>前向公式与缩放<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">LoRA 分支怎样与原线性层相加？</p><div class=\"dd-formula\" data-formula-id=\"peft-lora-forward\" data-display=\"mathml\"><math display=\"block\" aria-label=\"输出 h 等于基座权重 W 乘输入 x，加 alpha 除以秩 r 再乘 B A x；A 是 r 乘 k，B 是 d 乘 r\"><mrow><mi>h</mi><mo>=</mo><mi>W</mi><mi>x</mi><mo>+</mo><mfrac><mi>α</mi><mi>r</mi></mfrac><mi>B</mi><mi>A</mi><mi>x</mi><mo>,</mo><mspace width=\"0.8em\"/><mi>A</mi><mo>∈</mo><msup><mi>ℝ</mi><mrow><mi>r</mi><mo>×</mo><mi>k</mi></mrow></msup><mo>,</mo><mspace width=\"0.5em\"/><mi>B</mi><mo>∈</mo><msup><mi>ℝ</mi><mrow><mi>d</mi><mo>×</mo><mi>r</mi></mrow></msup></mrow></math></div><p class=\"dd-formula-note\"><code>x</code> 是 k 维输入，<code>W</code> 是冻结的 d×k 基座权重，<code>h</code> 是 d 维输出。<code>A</code> 先把 k 维输入压到 r 维，<code>B</code> 再把 r 维展开到 d 维；<code>ℝ</code> 表示矩阵元素是实数。<code>r</code> 是秩上限，<code>α</code> 是缩放系数，比例 <code>α/r</code> 控制低秩分支相对基座分支的强度。</p><p>常将 A 随机初始化、B 初始化为零，使训练开始时 ΔW=0，不改变基座行为。α/r 控制更新尺度；rank 增大若 α 不调，增量尺度会变化。dropout 是训练时随机丢弃部分分支信号的正则化手段，可只作用 LoRA 分支。</p><p>反向不更新 W，但梯度要穿过 W 传播到早层适配器和 A/B；所以基座计算与激活并未消失。若目标指标提高而通用能力下降，说明低秩分支改变了任务行为但产生回归，不能只按训练损失选择配置。</p><div class=\"dd-note warn\"><b>rank 不是“压缩比旋钮”而已。</b>　它改变可表达增量子空间，必须和 α、层、数据一起消融。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>运行示例：4096×4096 投影省多少可训练参数<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">rank=8 时，16.8M 参数的矩阵需要训练多少 LoRA 参数？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 250\" role=\"img\" aria-label=\"4096乘4096基座矩阵通过4096乘8和8乘4096低秩矩阵产生增量\"><rect x=\"20\" y=\"65\" width=\"170\" height=\"120\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"105\" y=\"92\" text-anchor=\"middle\" class=\"svg-t\">冻结 W</text><text x=\"105\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\">4096×4096</text><text x=\"105\" y=\"148\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">16,777,216 参数</text><text x=\"105\" y=\"170\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">仍参与前向</text><text x=\"240\" y=\"128\" class=\"svg-t\">+</text><rect x=\"285\" y=\"86\" width=\"105\" height=\"78\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"337\" y=\"112\" text-anchor=\"middle\" class=\"svg-t\">A: 8×4096</text><text x=\"337\" y=\"139\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">32,768</text><text x=\"420\" y=\"128\" class=\"svg-t\">→</text><rect x=\"455\" y=\"86\" width=\"105\" height=\"78\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"507\" y=\"112\" text-anchor=\"middle\" class=\"svg-t\">B: 4096×8</text><text x=\"507\" y=\"139\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">32,768</text><text x=\"590\" y=\"128\" class=\"svg-t\">=</text><rect x=\"615\" y=\"75\" width=\"70\" height=\"100\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"650\" y=\"104\" text-anchor=\"middle\" class=\"svg-t\">ΔW</text><text x=\"650\" y=\"129\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">秩≤8</text><text x=\"650\" y=\"151\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">65,536</text><text x=\"350\" y=\"218\" text-anchor=\"middle\" class=\"svg-t\">可训练比例 65,536 / 16,777,216 ≈ 0.391%</text></svg><figcaption>图 1　两个低秩矩阵只训练约 0.39% 参数，但完整基座矩阵仍要参与计算。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>rank</th><th>A+B 参数</th><th>相对 W</th><th>表达能力/代价</th></tr></thead><tbody><tr><td>4</td><td>32,768</td><td>.195%</td><td>最省，可能欠拟合</td></tr><tr><td>8</td><td>65,536</td><td>.391%</td><td>示例起点</td></tr><tr><td>32</td><td>262,144</td><td>1.563%</td><td>容量高、状态更多</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>省的是哪些内存，哪些仍然存在<span class=\"dd-badge eng\">资源</span></h2><p class=\"dd-lead\">只训练 0.39% 参数，训练显存为什么不会缩到 0.39%？</p><p>不为冻结 W 保存梯度与 Adam 一、二阶状态，适配器检查点也小；但基座权重、前向激活、反向所需中间值、临时工作区仍在。激活常随 batch、序列和层数主导。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>资源</th><th>全量微调</th><th>LoRA</th></tr></thead><tbody><tr><td>基座权重</td><td>需要</td><td>需要且冻结</td></tr><tr><td>基座梯度</td><td>需要</td><td>通常不存</td></tr><tr><td>基座优化器状态</td><td>需要</td><td>不需要</td></tr><tr><td>激活</td><td>需要</td><td>仍需要，可检查点</td></tr><tr><td>适配器状态</td><td>无</td><td>小但需梯度/优化器</td></tr></tbody></table></div><p>训练速度也不会按参数比例加速，因为 W x 的大矩阵乘仍占主要 FLOPs。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>目标模块决定任务能改哪里<span class=\"dd-badge eng\">调参</span></h2><p class=\"dd-lead\">只对 Q/V 投影加 LoRA 与覆盖所有线性层，有何结构差异？</p><p>Transformer 注意力中的 Q（查询）、K（键）、V（值）和 O（输出）投影，分别参与“找谁、怎样匹配、取什么信息、怎样送回主干”；MLP 是每层随后进行特征变换的前馈网络，gate/up/down 是常见实现里的门控、升维和降维投影。这里的<b>降维</b>只表示把向量的坐标数量从较多变成较少，用于让 MLP 输出回到主干维度；它不是在这一节把样本特征压成二维图。对这些模块加 LoRA，就是选择允许任务数据改动哪些计算环节。</p><p>目标层少更省、更易控，可能容量不足；覆盖更多层提升适配能力也增加过拟合与部署开销。配置输入是候选模块、rank 和相同训练预算，输出是各方案的任务、通用、安全和未见分布指标。</p><p>做受控消融：固定数据与总训练 token，比较 QV、全部注意力、注意力+MLP；rank 可按层不同。不要只看训练 loss，需目标任务、通用能力、安全与未见分布。若加更多层后训练损失下降而留出收益停滞，应解释为容量没有转化为泛化，而不是继续无条件扩层。</p><div class=\"dd-note warn\"><b>模块名依架构而异。</b>　配置匹配不到目标层可能静默训练零参数；启动时列出可训练参数和层路径并断言数量。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>QLoRA 把冻结基座量化存储<span class=\"dd-badge eng\">量化</span></h2><p class=\"dd-lead\">基座是 4-bit，梯度怎样通过它到达 LoRA？</p><p>QLoRA 是“量化后的冻结基座 + 可训练 LoRA”的组合。量化把基座权重用更少比特近似存储；4-bit 表示每个量化编码只有 16 种取值，而计算时会把编码还原成较高精度近似值。基座参数不更新，但这次矩阵运算仍把梯度传给 A/B。</p><p>NF4 是针对近似正态分布权重设计的 4-bit 编码；double quantization 连量化尺度本身也再压缩；分页优化器在内存紧张时分批迁移优化器状态。它们分别处理权重表示、量化元数据和峰值内存，并不是三种精度相同的名字。</p><p>QLoRA 组合了量化误差与低秩适配上限。输入是量化基座、LoRA 配置和任务数据，输出是适配器及其量化训练配方。训练完成后合并到高精基座再重新量化，与保持分离推理不是同一产物；若两种产物指标不同，应归因到合并和再量化路径并分别评测。</p><div class=\"dd-note math\"><b>资源边界：</b>训练内存下降不等于训练 FLOPs 同比例下降；反量化与基座前向、反向仍然发生。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>合并与动态切换有不同工程边界<span class=\"dd-badge eng\">部署</span></h2><p class=\"dd-lead\">将 ΔW 写回 W 后，为什么文件更简单却更难回滚？</p><p>合并 <code>W←W+(α/r)BA</code> 可消除分支额外矩阵乘，适合固定单适配器；分离保存便于按租户/任务切换和回滚，但调度需将相同适配器批在一起，频繁加载会抖动。</p><p>适配器必须绑定基座哈希、tokenizer、目标模块、rank、α、dtype 和训练数据版本。错基座即使形状相同也会产生未验证行为。合并顺序与量化顺序影响结果，产物记录完整配方。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>形态</th><th>优势</th><th>风险</th></tr></thead><tbody><tr><td>分离</td><td>小文件、可切换/回滚</td><td>额外算子、批调度、错配</td></tr><tr><td>合并</td><td>单权重、推理简单</td><td>新大文件、失去独立开关</td></tr><tr><td>多适配器组合</td><td>尝试能力组合</td><td>尺度/方向干扰，无保证</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>小参数比例不代表小行为变化<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">只改 0.1% 参数，为什么能让模型学会新格式，也能破坏安全拒答？</p><p>神经网络行为由参数方向与放大链决定，不按改动数量线性变化。少量低秩更新作用于多层和所有输入，能显著重排 logits；窄数据还会过拟合措辞、遗忘通用能力或形成触发器。</p><p>训练数据需许可、去重和防投毒；第三方适配器视为可执行模型制品，扫描来源、签名和行为。对目标、通用、长上下文、多语言、安全、工具和校准做回归；逐层/逐适配器消融定位问题。</p><div class=\"dd-note warn\"><b>适配器供应链：</b>小文件易传播，也易绕过完整模型审查；加载权限应等同模型代码/权重。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>何时选 LoRA，何时选其他方案<span class=\"dd-badge intuition\">决策</span></h2><p class=\"dd-lead\">任务只需要新知识、固定格式或深层能力改变时，方案相同吗？</p><p>知识频繁更新优先 RAG/工具；少量格式和行为可先提示/约束；多租户任务适配、有限算力适合 LoRA；需要广泛能力重塑且数据/资源充分可考虑全量微调；端侧体积目标还需蒸馏/量化。</p><p>比较同预算基线：提示、检索、LoRA、全量微调和更强模型。计算训练、存储、适配器路由、延迟、评测与维护的每成功任务成本，而非只看 GPU 能否跑。</p><div class=\"dd-note\"><b>停止条件：</b>rank/层数增加后真实留出增益平台而通用/安全退化上升，应停止扩适配器容量。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">LoRA 是低秩参数化的训练方法，不是“零成本微调”或“低风险补丁”。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>训练参数少，全部显存同比少</td><td>基座和激活仍在，主要省梯度/优化器</td></tr><tr><td>rank 越大越好</td><td>容量、过拟合、状态和尺度需平衡</td></tr><tr><td>QLoRA 训练 4-bit 梯度</td><td>低位基座冻结，计算时反量化，训练 LoRA</td></tr><tr><td>适配器可配任何同形基座</td><td>必须绑定精确基座与模块语义</td></tr><tr><td>改 0.1% 参数风险也 0.1%</td><td>小增量可全局改变 logits 和安全行为</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>矩阵秩、微调、反向传播与优化器状态</td></tr><tr><td><b>本页核心</b></td><td>低秩增量、rank/alpha、目标模块、合并/切换</td></tr><tr><td>组合</td><td>量化/QLoRA、模型合并、蒸馏</td></tr><tr><td>生产</td><td>模型路由、数据治理、评测与供应链安全</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>确定任务是否需参数适配</li><li>选择目标层/rank/alpha</li><li>冻结基座并训练 A/B</li><li>消融容量与数据覆盖</li><li>分离或按配方合并部署</li><li>回归目标/通用/安全并记录血缘</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>4096×4096、r=8 的 LoRA 参数多少？</li><li>LoRA 主要省哪些状态？</li><li>QLoRA 的基座如何参与计算？</li><li>合并后要记录什么？</li><li>为何仍需安全回归？</li><li>假设“PEFT / LoRA：冻结主干，只学习低秩权重增量”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“PEFT / LoRA：冻结主干，只学习低秩权重增量”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>8×4096+4096×8=65,536，约原矩阵 0.391%。</li><li>冻结基座的梯度、优化器状态和任务检查点。</li><li>低位存储、前向反量化，冻结不更新但梯度传到 LoRA。</li><li>基座哈希、适配器、目标层、rank、alpha、dtype、顺序和量化配方。</li><li>少量低秩更新可全局改变输出和拒答行为。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2106.09685\" target=\"_blank\" rel=\"noopener\">LoRA</a>：低秩权重适配</li><li><a href=\"https://arxiv.org/abs/2305.14314\" target=\"_blank\" rel=\"noopener\">QLoRA</a>：量化基座上的高效微调</li><li><a href=\"https://arxiv.org/abs/1902.00751\" target=\"_blank\" rel=\"noopener\">Parameter-Efficient Transfer Learning for NLP</a>：Adapter 参数高效迁移</li><li><a href=\"https://arxiv.org/abs/2303.10512\" target=\"_blank\" rel=\"noopener\">AdaLoRA</a>：自适应秩分配</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
